import numpy as np

# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: This is a compact implementation of a randomized direct search algorithm for
#          black-box function minimization. It maintains a population of candidate
#          solutions, and iteratively replaces the worst candidate with a new one
#          generated by perturbing the current best.
# Search state: The search state is represented by a numpy array of candidate
#               solutions. The size of this array is determined by the initial
#               budget and dimension.
# Candidate generation: New candidate solutions are generated by perturbing the
#                      current best solution with a random Gaussian offset.
# Selection and replacement: In each iteration, the candidate solution with the
#                            highest objective function value is replaced with
#                            the new candidate.
# Adaptation: The standard deviation of the Gaussian perturbation is adapted
#             based on the distance between the current best and worst solutions.
# Exploration mechanisms: The Gaussian perturbation provides a balance of
#                         exploration and exploitation.
# Exploitation mechanisms: The algorithm focuses the search around the current
#                          best solution.
# Boundary handling: If a new candidate solution falls outside the bounds, it is
#                    projected back onto the nearest valid point.
# Budget strategy: The algorithm uses the entire provided evaluation budget,
#                  without exceeding it.
# Closest known influences: This algorithm is inspired by classic randomized
#                          direct search methods, such as the Nelder-Mead
#                          simplex method and evolutionary strategies.
# Novelty or unusual aspects: The adaptive perturbation step and the way the
#                            budget is utilized are somewhat unusual.
# Failure modes: The algorithm may struggle on highly multimodal functions or
#                functions with very narrow optima, as the Gaussian perturbation
#                may not be able to effectively explore such landscapes.
# ALGORITHM_ANALYSIS_NOTE_END

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim
        self.population = np.random.uniform(0, 1, (budget, dim))

    def __call__(self, func):
        best_x = None
        best_y = float('inf')

        for _ in range(self.budget):
            # Evaluate all candidates
            ys = [func(x) for x in self.population]

            # Find the best and worst candidates
            best_idx = np.argmin(ys)
            best_x = self.population[best_idx]
            best_y = ys[best_idx]
            worst_idx = np.argmax(ys)
            worst_x = self.population[worst_idx]

            # Generate a new candidate by perturbing the best
            new_x = best_x + np.random.normal(0, np.linalg.norm(best_x - worst_x), self.dim)

            # Clip the new candidate to the bounds
            new_x = np.clip(new_x, func.lower, func.upper)

            # Replace the worst candidate with the new one
            self.population[worst_idx] = new_x

        return best_x, best_y
